 32	     * @param requestDto 결제 및 배송 요청 정보
 33	     */
 34	    public void sendOrderProcessingEvent(Long orderId, String userEmail, PayAndShipmentRequestDto requestDto) {
 35	        try {
 36	            OrderProcessingEvent event = OrderProcessingEvent.create(orderId, userEmail, requestDto);
 37	
 38	            log.info("주문 처리 이벤트 발행 시작: 주문ID={}, 사용자={}, 이벤트ID={}",
 39	                    orderId, userEmail, event.getEventId());
 40	
 41	            // 주문 ID를 키로 사용하여 순서 보장
 42	            CompletableFuture<SendResult<String, OrderProcessingEvent>> future =
 43	                    kafkaTemplate.send(ORDER_PROCESSING_TOPIC, orderId.toString(), event);
 44	
 45	            future.whenComplete((result, ex) -> {
 46	                if (ex == null) {
 47	                    log.info("주문 처리 이벤트 발행 성공: 주문ID={}, 파티션={}, 오프셋={}",
 48	                            orderId,
 49	                            result.getRecordMetadata().partition(),
 50	                            result.getRecordMetadata().offset());
 51	                } else {
 52	                    log.error("주문 처리 이벤트 발행 실패: 주문ID={}, 오류={}", orderId, ex.getMessage(), ex);
 53	                }
 54	            });
 55	
 56	        } catch (Exception e) {
 57	            log.error("주문 처리 이벤트 발행 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
 58	            throw new RuntimeException("주문 처리 이벤트 발행 실패", e);
 59	        }
 60	    }
