 65	    public void sendOrderRetryEvent(OrderProcessingEvent originalEvent) {
 66	        try {
 67	            if (originalEvent.isMaxRetryExceeded()) {
 68	                log.warn("최대 재시도 횟수 초과로 재시도 중단: 주문ID={}, 재시도횟수={}",
 69	                        originalEvent.getOrderId(), originalEvent.getRetryCount());
 70	                return;
 71	            }
 72	
 73	            OrderProcessingEvent retryEvent = originalEvent.withRetry();
 74	
 75	            log.info("주문 처리 재시도 이벤트 발행: 주문ID={}, 재시도횟수={}",
 76	                    retryEvent.getOrderId(), retryEvent.getRetryCount());
 77	
 78	            CompletableFuture<SendResult<String, OrderProcessingEvent>> future =
 79	                    kafkaTemplate.send(ORDER_RETRY_TOPIC, retryEvent.getOrderId().toString(), retryEvent);
 80	
 81	            future.whenComplete((result, ex) -> {
 82	                if (ex == null) {
 83	                    log.info("주문 처리 재시도 이벤트 발행 성공: 주문ID={}", retryEvent.getOrderId());
 84	                } else {
 85	                    log.error("주문 처리 재시도 이벤트 발행 실패: 주문ID={}, 오류={}",
 86	                            retryEvent.getOrderId(), ex.getMessage(), ex);
 87	                }
 88	            });
 89	
 90	        } catch (Exception e) {
 91	            log.error("주문 처리 재시도 이벤트 발행 중 오류 발생: 주문ID={}, 오류={}",
 92	                    originalEvent.getOrderId(), e.getMessage(), e);
 93	        }
 94	    }
