497	    @Transactional
498	    public void updatePaymentStatus(Payment payment, PaymentStatus newStatus) {
499	        Instant start = Instant.now();
500	        try {
501	            if (payment == null) {
502	                throw new PaymentNotFoundException("결제 정보가 없습니다.");
503	            }
505	            if (!payment.getStatus().canTransitionTo(newStatus)) {
506	                throw new PaymentException(PaymentErrorCode.INVALID_PAYMENT_STATUS,
507	                        "현재 상태(" + payment.getStatus() + ")에서 " + newStatus + " 상태로 변경할 수 없습니다.");
508	            }
510	            log.info("결제 상태 변경: 결제ID={}, 현재상태={}, 새상태={}",
511	                    payment.getId(), payment.getStatus(), newStatus);
513	            payment.updateStatus(newStatus);
514	            paymentRepository.save(payment);
516	            log.info("결제 상태 변경 완료: 결제ID={}, 상태={}", payment.getId(), newStatus);
518	            // 처리 시간 로깅
519	            Instant end = Instant.now();
520	            Duration duration = Duration.between(start, end);
521	            log.debug("결제 상태 변경 처리 시간: {}ms", duration.toMillis());
522	        } catch (PaymentException e) {
523	            log.error("결제 상태 변경 실패: 결제ID={}, 에러코드={}, 메시지={}",
524	                    payment != null ? payment.getId() : "null",
525	                    e.getErrorCode().getCode(), e.getMessage());
526	            throw e; // 이미 PaymentException이면 그대로 전파
527	        } catch (Exception e) {
528	            log.error("결제 상태 변경 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
529	                    payment != null ? payment.getId() : "null", e.getMessage(), e);
530	            throw new PaymentException(PaymentErrorCode.PAYMENT_UPDATE_FAILED,
531	                    "결제 상태 변경 중 오류가 발생했습니다.", e);
532	        }
533	    }
542	    @Transactional
543	    public String refundPayment(Long paymentId) {
544	        Instant start = Instant.now();
545	        try {
546	            log.info("결제 환불 요청 시작: 결제ID={}", paymentId);
548	            // 1. Payment 정보 조회
549	            Payment payment = paymentRepository.findById(paymentId)
550	                    .orElseThrow(() -> new PaymentNotFoundException("결제 ID: " + paymentId + "를 찾을 수 없습니다."));
552	            // 2. 현재 상태 확인
553	            if (!payment.getStatus().canTransitionTo(PaymentStatus.REFUND_REQUESTED)) {
554	                throw new PaymentException(PaymentErrorCode.INVALID_PAYMENT_STATUS,
555	                        "현재 상태에서 환불 요청을 진행할 수 없습니다. 현재 상태: " + payment.getStatus());
556	            }
558	            // 3. 포트원 API를 통해 환불 요청
559	            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
560	                throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
561	                        "환불 가능한 결제 ID가 없습니다.");
562	            }
564	            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());
566	            if (refundSuccess) {
567	                payment.updateStatus(PaymentStatus.REFUNDED); // 상태를 REFUNDED로 변경
568	                paymentRepository.save(payment);
569	                log.info("결제 환불 요청 성공: 결제ID={}, 상태=REFUNDED", paymentId);
571	                // 환불 성공 시 알림 발송
572	                sendRefundNotification(payment);
574	                // 처리 시간 로깅
575	                Instant end = Instant.now();
576	                Duration duration = Duration.between(start, end);
577	                log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
579	                return "환불이 성공적으로 완료되었습니다.";
580	            } else {
581	                payment.updateStatus(PaymentStatus.REFUND_REQUESTED); // 환불 요청 상태로 업데이트
582	                paymentRepository.save(payment);
583	                log.warn("결제 환불 요청 실패: 결제ID={}, 상태=REFUND_REQUESTED", paymentId);
584	                return "환불 요청이 실패하였습니다. 관리자에게 문의하세요.";
585	            }
586	        } catch (PaymentException e) {
587	            log.error("결제 환불 요청 실패: 결제ID={}, 에러코드={}, 메시지={}",
588	                    paymentId, e.getErrorCode().getCode(), e.getMessage());
589	            throw e; // 이미 PaymentException이면 그대로 전파
590	        } catch (Exception e) {
591	            log.error("결제 환불 요청 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
592	                    paymentId, e.getMessage(), e);
593	            throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
594	                    "환불 요청 중 오류가 발생했습니다: " + e.getMessage());
595	        }
596	    }
603	    private void sendRefundNotification(Payment payment) {
604	        try {
605	            User user = payment.getUser();
606	            if (user == null) {
607	                log.warn("환불 알림 발송 실패: 결제ID={}, 사용자 정보가 없습니다.", payment.getId());
608	                return;
609	            }
611	            Order order = payment.getOrder();
612	            String orderInfo = order != null ? "주문 ID: " + order.getId() : "환불금액: " + payment.getPaidAmount() + "원";
614	            notificationCommandService.createNotification(
615	                    user.getId(),
616	                    NotificationCategory.SHOPPING,
617	                    NotificationType.REFUND,
618	                    "결제가 환불되었습니다. " + orderInfo
619	            );
620	            log.debug("환불 알림 전송 완료: 사용자ID={}, 결제ID={}", user.getId(), payment.getId());
622	            // 판매자 알림 - 주문과 연결된 판매 정보가 있는 경우
623	            if (order != null) {
624	                Sale sale = null;
626	                // OrderBid를 통한 Sale 조회
627	                OrderBid orderBid = order.getOrderBid();
628	                if (orderBid != null) {
629	                    sale = orderBid.getSale();
630	                }
631	                // SaleBid를 통한 Sale 조회
632	                else {
633	                    SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
634	                    if (saleBid != null) {
635	                        sale = saleBid.getSale();
636	                    }
637	                }
639	                if (sale != null && sale.getSeller() != null) {
640	                    User seller = sale.getSeller();
641	                    notificationCommandService.createNotification(
642	                            seller.getId(),
643	                            NotificationCategory.SHOPPING,
644	                            NotificationType.REFUND,
645	                            "구매자의 결제가 환불되었습니다. 판매 ID: " + sale.getId()
646	                    );
647	                    log.debug("판매자 환불 알림 전송 완료: 판매자ID={}, 판매ID={}",
648	                            seller.getId(), sale.getId());
650	                    // 중고거래 특성상 판매 완료 후에는 상태를 변경하지 않음
651	                    // 판매자가 직접 새로운 판매 게시글을 등록해야 함
652	                }
653	            }
654	        } catch (Exception e) {
655	            // 알림 전송 실패 로깅만 하고 예외는 발생시키지 않음
656	            log.warn("환불 알림 전송 중 오류 발생: 결제ID={}, 오류={}",
657	                    payment.getId(), e.getMessage());
658	        }
659	    }
660	}

